// ============================================
// VALIDATION INPUT - Entity Rating
// RFC-049 Entity Storage Architecture
// ============================================

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];
const startTime = Date.now();

// --- Get tenant_id from header or body ---
const tenantId = headers['x-tenant-id'] || headers['X-Tenant-ID'] || body.tenant_id || ctx.tenant_id || null;

// --- Backend API configuration ---
const backendApiUrl = body.backend_api_url || ctx.backend_api_url || null;
const backendServiceToken = body.backend_service_token || ctx.backend_service_token || null;

// --- Required fields ---
const action = (body.action || ctx.action || '').toLowerCase();
const validActions = ['rate', 'get', 'delete'];
if (!action || !validActions.includes(action)) {
  errors.push(`action invalide: '${action}' (doit etre: ${validActions.join(', ')})`);
}

const entityId = body.entity_id || ctx.entity_id || '';
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!entityId) {
  errors.push('entity_id requis');
} else if (!uuidRegex.test(entityId)) {
  errors.push('entity_id invalide (format UUID requis)');
}

const userId = body.user_id || ctx.user_id || '';
if (!userId || userId.trim().length === 0) {
  errors.push('user_id requis');
}

// --- Optional fields ---
const entityType = body.entity_type || ctx.entity_type || '';
const validEntityTypes = ['recipe', 'document', 'course', 'quiz', 'flashcard'];
if (entityType && !validEntityTypes.includes(entityType)) {
  errors.push(`entity_type invalide: '${entityType}' (doit etre: ${validEntityTypes.join(', ')})`);
}
const guildId = body.guild_id || ctx.guild_id || null;
const rating = body.rating !== undefined ? body.rating : (ctx.rating !== undefined ? ctx.rating : null);

// --- Conditional validations based on action ---
if (action === 'rate') {
  if (rating === null || rating === undefined) {
    errors.push('rating requis pour action=rate');
  } else if (!Number.isInteger(rating) || rating < 1 || rating > 5) {
    errors.push('rating doit etre un entier entre 1 et 5');
  }
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId || null,
    guild_id: guildId,
    startTime: startTime
  };
}

return {
  valid: true,
  action: action,
  entity_id: entityId,
  entity_type: entityType,
  user_id: userId.trim(),
  guild_id: guildId,
  rating: rating,
  tenant_id: tenantId,
  backend_api_url: backendApiUrl,
  backend_service_token: backendServiceToken,
  startTime: startTime
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;
const startTime = input.startTime || Date.now();

return {
  success: false,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'postgresql',
    mode: 'error',
    latency_ms: Date.now() - startTime,
    user_id: input.user_id,
    guild_id: input.guild_id
  }
};

