// FORMAT RATE RESPONSE
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();
const latency = Date.now() - startTime;

// Handle API errors
const statusCode = input.statusCode || 200;
const body = input.body || input;

if (statusCode >= 400 || body.error || body.detail) {
  return {
    success: false,
    error: {
      code: 'API_ERROR',
      message: body.error?.message || body.detail || 'Failed to rate entity',
      http_status: statusCode >= 400 ? statusCode : 500
    },
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    _trace: {
      service_response: body,
      provider: 'postgresql',
      action: 'rate',
      latency_ms: latency,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id
    }
  };
}

// Success response
return {
  success: true,
  data: {
    entity_id: prevData.entity_id,
    rating: prevData.rating,
    new_average: body.new_average || body.average || null,
    total_ratings: body.total_ratings || body.total || null
  },
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  _trace: {
    service_response: body,
    provider: 'postgresql',
    action: 'rate',
    entity_type: prevData.entity_type,
    entity_id: prevData.entity_id,
    latency_ms: latency,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id
  }
};

